const writer = H.seat('writer').role(writerRole).skill(writePage).models(sonnet);

const linkCheck = H.command('link-check')
  .input(z.object({ path: z.string() }))
  .output(z.object({ ok: z.boolean(), broken: z.array(z.string()) }))
