  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['npx', 'markdown-link-check', '--quiet', input.path]);
    return { ok: result.code === 0, broken: result.stdout.split('\n').filter(line => line.includes('✖')) };
